def main():
    viejos = json.load(open(os.path.join(AQUI, 'posts.json')))
    salida = []
    for v in viejos:
        texto = v['texto'].split('\n\nLo escribí completo aquí:')[0]
        salida.append({'orden': v['orden'], 'articulo': v['post'] and None, 'titulo': v['articulo'], 'formato': 'gif' if v['visual'].endswith('.gif') else 'imagen',
                       'texto': texto, 'liga': v['liga'], 'visual': v['visual'], 'estado': 'pausado 28-oct-2026: en borradores de X, sin fecha'})
    # n del artículo de los 9 viejos, por su liga
    inv = {v: int(k) for k, v in PUB.items()}
    for s in salida:
        s['articulo'] = inv[s['liga'].rsplit('/', 1)[1]]
    for orden, n, formato, texto in NUEVOS:
        salida.append({'orden': orden, 'articulo': n, 'titulo': ARTS[n], 'formato': formato, 'texto': texto, 'liga': liga(n),
                       'visual': None, 'estado': 'propuesto 28-oct-2026: sin crear en X'})
    for s in salida:
        s['texto_x'] = s['texto'] + '\n\nLo escribí completo aquí: ' + s['liga']
    json.dump(salida, open(os.path.join(AQUI, 'posts.json'), 'w'), ensure_ascii=False, indent=1)
    print(len(salida), 'posts;', sum(1 for s in salida if s['formato'] == 'texto'), 'texto,', sum(1 for s in salida if s['formato'] == 'gif'), 'gif,', sum(1 for s in salida if s['formato'] == 'imagen'), 'imagen')
    for s in salida:
        print(s['orden'], len(s['texto_x']), s['formato'], s['titulo'][:40])


if __name__ == '__main__':
    main()
